class Solution {
  public int countPermutations(int[] complexity) {
    final long MOD = 1_000_000_007L;
    // computer 0 is the only root, so it must be strictly the easiest one
    for (int i = 1; i < complexity.length; i++) {
      if (complexity[i] <= complexity[0]) return 0;
    }
    long ways = 1;
    for (int i = 2; i < complexity.length; i++) ways = ways * i % MOD; // (n - 1)!
    return (int) ways;
  }
}
